export const LUA_EXEC = "'use strict';\n// Runs one Lua source chunk on the game's own thread, at entry of the native\n// LUI frame (0x337c1c0), where no Lua is executing. Never call from an RPC thread.\nconst b=Process.getModuleByName('libgame.so').base,at=x=>b.add(x);\nconst lVar=at(0x54bcd08).readPointer();\nconst load=new NativeFunction(at(0x4490778),'int',['pointer','pointer','size_t','pointer','pointer']);\nconst pcall=new NativeFunction(at(0x4486bc4),'int',['pointer','int','int','int']);\nconst tostr=new NativeFunction(at(0x4483720),'pointer',['pointer','int','pointer']);\nconst name=Memory.allocUtf8String('=wzm_bridge');\nlet pending=null;\nInterceptor.attach(at(0x337c1c0),{onEnter(){\n if(pending===null)return;\n const L=lVar.readPointer();\n if(L.isNull())return;\n const src=pending;pending=null;\n const top=L.add(0x28).readPointer(),stk0=L.add(0x38).readPointer(),topOff=(top.compare(stk0)>=0&&top.compare(L.add(0x30).readPointer())<=0)?top.sub(stk0):null;\n let out={tid:Process.getCurrentThreadId(),L:L.toString()};\n try{\n  const buf=Memory.allocUtf8String(src);\n  out.load=load(L,buf,src.length,name,ptr(0));\n  if(out.load===0)out.pcall=pcall(L,0,1,0);\n  const s=tostr(L,-1,ptr(0));\n  out.result=s.isNull()?null:s.readUtf8String();\n }catch(e){out.exception=String(e);}\n L.add(0x28).writePointer(topOff===null?top:L.add(0x38).readPointer().add(topOff));\n send({kind:'lua_result',out});\n}});\nrpc.exports={run(src){pending=src;return true;}};\nsend({kind:'ready',base:b.toString(),L:lVar.readPointer().toString()});\n";
export const FAKE_PLAYER_JS = "\nconst b=Process.getModuleByName('libgame.so').base,at=x=>b.add(x);\nconst mmap=new NativeFunction(Module.getGlobalExportByName('mmap'),'pointer',['pointer','size_t','int','int','int','long']);\nconst bindStats=new NativeFunction(at(0x331aaec),'void',['int','int','int']);\nlet done=false;\nInterceptor.attach(at(0x337c1c0),{onEnter(){\n if(done)return;\n done=true;\n const table=at(0x54bcb10).readPointer(),size=at(0xc13b090).readU32();\n for(const group of [0,1]){\n  const entry=table.add(group*0x248);\n  if(entry.readPointer().isNull()){entry.writePointer(mmap(ptr(0),0x66000,3,0x22,-1,0));entry.add(8).writeU32(size);}\n  entry.add(0x247).writeU8(0);\n  entry.add(0x244).writeU8(1);\n }\n const bound=[];\n for(let group=0;group<14;group++){\n  const slot=at(0xc1df528+group*16).readS32();\n  if(slot>=0)at(0xc1de450).add(slot*0x68+0x18).writeU32(2);\n  if(at(0xc1df520+group*16).readPointer().isNull())continue;\n  bindStats(0,0,group);\n  bindStats(0,1,group);\n  bound.push(group);\n }\n send({size,bound});\n}});\n";
export const FAKE_PLAYER_LUA = "-- Fake local profile. Runs after fake_player_data.py has bound the stats handles.\nlocal W=rawget(_G,\"_WZM\")\nlocal core\nfor k,f in pairs(W.pdo) do if tostring(k):find(\"08b73907b55\") then core=f end end\nlocal r=core(0,CoD.StatsGroup.Ranked)\nr.progression.playerLevel.xp:set(100000)\nr.kills:set(1234)\nr.deaths:set(617)\nr.gamesPlayed:set(100)\nreturn \"profile xp=\"..tostring(r.progression.playerLevel.xp:get())..\" kills=\"..tostring(r.kills:get())\n";
export const PARTY_INJECT = "// Offline bot injection experiment (memory-only, one shot).\n// Real path: Lobby.AddBots -> 0x1604408 -> local apply 0x162a90c (pa_manage_bots)\n//   -> party bot members; game script -> addtestclient 0x3cd64e8 -> 0x3cd6670 -> 0x3ccc9b0.\n// Offline, the local party has no session: party+0x4650 and party+0x54 are 0, so\n// the host gate 0x160ac1c and eligibility 0x3910ee0 both fail. This fills them\n// with a nonzero local marker, then asks for bots through the original code.\n// addtestclient is called natively on the server thread (chained in front of the\n// host's frame thunk via the veneer at 0x3cd7b20) so that hooks and Stalker see it.\n{\n'use strict';\nconst b=Process.getModuleByName('libgame.so').base,at=n=>b.add(n);\nconst E=globalThis.WZM_BOT_ENV||{};\nconst COUNT=E.count||5, TEAM=E.team===undefined?1:E.team, DIFF=E.diff||0, CALLS=E.calls||1;\nconst getParty=new NativeFunction(at(0x1601ffc),'pointer',[]);\nconst gate=new NativeFunction(at(0x160ac1c),'int',['pointer']);\nconst cap=new NativeFunction(at(0x160aa70),'int',['pointer','int']);\nconst apply=new NativeFunction(at(0x162a90c),'int',['pointer','pointer'],{traps:'all'});\nconst req=Memory.alloc(16);\nconst keep=globalThis.wzmBotKeep=globalThis.wzmBotKeep||[];\nfunction slots(){const n=at(0x54cafa8).readPointer().readS32(),s=at(0x54cafb0).readPointer(),v=[];for(let i=0;i<Math.min(n,20);i++){const p=s.add(i*8).readPointer();if(!p.isNull()&&p.add(8).readU8())v.push([i,p.add(8).readU8(),p.add(0xb668).readU32()]);}return v;}\nfunction members(p){const arr=p.add(0x20f8).readPointer(),n=p.add(0x4050+0x3c0).readS32(),v=[];if(arr.isNull())return {n,arr:'null'};for(let i=0;i<Math.min(Math.max(n,0),24);i++){const st=arr.add(i*0x240+0x1f2).readU8();if(st)v.push([i,st]);}return {n,v};}\nfunction fields(p){return {f4650:p.add(0x4650).readU64().toString(16),f54:p.add(0x54).readU64().toString(16),gate:gate(p)&1,cap:cap(p,COUNT)&1,members:members(p)};}\n\n// ---- native server-thread call gate ----\nconst veneer=at(0x3cd7b20);\nconst oldThunk=veneer.add(8).readPointer();\nconst cg=Memory.alloc(64);cg.writeU64(0);keep.push(cg);  // +0 request, +8 result, +0x10 inCall, +0x18 fn, +0x20 x0, +0x28 x1\nconst thunk=Memory.alloc(Process.pageSize);keep.push(thunk);\nMemory.protect(thunk,Process.pageSize,'rwx');\n{const w=new Arm64Writer(thunk,{pc:thunk});\n w.putPushRegReg('x29','lr');\n for(const[x,y]of[['x0','x1'],['x2','x3'],['x4','x5'],['x6','x7']])w.putPushRegReg(x,y);\n w.putLdrRegAddress('x16',cg);w.putLdrRegRegOffset('x17','x16',0);w.putCbzRegLabel('x17','skip');\n w.putStrRegRegOffset('xzr','x16',0);\n w.putLdrRegRegOffset('x0','x16',0x20);w.putLdrRegRegOffset('x1','x16',0x28);w.putLdrRegRegOffset('x16','x16',0x18);w.putBlrReg('x16');\n w.putLdrRegAddress('x16',cg);w.putStrRegRegOffset('x0','x16',8);\n w.putLabel('skip');\n for(const[x,y]of[['x6','x7'],['x4','x5'],['x2','x3'],['x0','x1']])w.putPopRegReg(x,y);\n w.putPopRegReg('x29','lr');\n w.putLdrRegAddress('x16',oldThunk);w.putBrReg('x16');w.flush();}\nconst ins0=veneer.readU32(),ins1=veneer.add(4).readU32();\n// veneer is \"ldr x16,#8; br x16; .quad target\": only the literal changes\nif(ins0!==0x58000050||ins1!==0xd61f0200)throw Error('unexpected veneer '+ins0.toString(16)+' '+ins1.toString(16));\nMemory.patchCode(veneer.add(8),8,c=>c.writePointer(thunk));\nfunction restore(){Memory.patchCode(veneer.add(8),8,c=>c.writePointer(oldThunk));}\nglobalThis.wzmBotRestore=restore;\n\n// ---- trace of the connection handler while our call runs ----\nlet inCall=false;const blocks=[],calls=[];const LO=0x3ccc9b0,HI=0x3cd0000;\nInterceptor.attach(at(0x3cd64e8),{onEnter(){inCall=cg.add(16).readU32()===1;},onLeave(r){if(inCall)send({s:'botAddTestLeave',ret:r.toString()});inCall=false;}});\nInterceptor.attach(at(0x3cd6670),{onEnter(a){if(inCall)send({s:'botFactoryEnter',name:a[0].readCString(),head:a[1].toInt32(),body:a[2].toInt32()});},onLeave(r){if(inCall)send({s:'botFactoryLeave',ret:r.toString()});}});\nInterceptor.attach(at(LO),{onEnter(a){\n if(!inCall)return;this.st=true;\n if(E.fixType!==false){const ad=a[0];const before=Array.from(new Uint8Array(ad.readByteArray(16)),x=>x.toString(16).padStart(2,'0')).join('');\n  // known-good bot address (all successful runs): 00ff00ff 0000 | type 01 | 03 | id | channel 1\n  // an all-zero prefix sends the handler down a path that faults (0x7405176050); keep the channel as built\n  if(ad.readU32()===0)ad.writeByteArray([0x00,0xff,0x00,0xff,0x00,0x00]);ad.add(6).writeU8(1);\n  send({s:'botAddrFixed',before});}\n try{send({s:'botHandlerEnter',addr:Array.from(new Uint8Array(a[0].readByteArray(24)),x=>x.toString(16).padStart(2,'0')).join('')});}catch(e){}\n if(!E.stalk){send({s:'botHandlerFast'});return;}\n this.stalked=true;\n Stalker.follow(Process.getCurrentThreadId(),{transform(it){let ins;while((ins=it.next())!==null){\n  const off=ins.address.sub(b).toInt32();\n  if(off>=LO&&off<HI){\n   if(ins.mnemonic==='bl'){const tgt=ptr(ins.operands[0].value).sub(b).toInt32();it.putCallout(()=>{if(calls.length<3000)calls.push([off,tgt]);});}\n   else if(ins.mnemonic==='blr'){it.putCallout(()=>{if(calls.length<3000)calls.push([off,-1]);});}\n   if(ins.mnemonic.startsWith('b.')||['cbz','cbnz','tbz','tbnz','ret'].includes(ins.mnemonic))it.putCallout(()=>{if(blocks.length<3000)blocks.push(off);});\n  }\n  it.keep();}}});\n},onLeave(r){if(!this.st)return;if(!this.stalked){send({s:'botHandlerLeave',ret:r.toString(),slots:slots()});return;}Stalker.unfollow(Process.getCurrentThreadId());Stalker.flush();\n const hx=x=>'0x'+(x>>>0).toString(16);\n send({s:'botHandlerTrace',ret:r.toString(),blocks:blocks.map(hx),calls:calls.map(([a,c])=>hx(a)+'>'+(c<0?'blr':hx(c)))});}});\n\nfor(const [n,o] of [['botClientInit',0x3cd9fc4],['botRejectSend',0x3ba1708],['botSetupCheck',0x3f0a088]]){try{Interceptor.attach(at(o),{onEnter(){if(inCall)send({s:n,t:Date.now()});},onLeave(r){if(inCall)send({s:n+'Ret',r:r.toString()});}});}catch(e){send({s:'hookSkip',n,e:String(e)});}}\n\n// Bots have no network endpoint: the send routine 0x3b9eab4 gets a null\n// network object for them and faults at 0x3b9eb90. Make that case a no-op.\n{const sendTarget=at(0x3b9eab4);const sendOrig=new NativeFunction(sendTarget,'uint64',['pointer','pointer','pointer','pointer']);\n let skipped=0;\n const cb=new NativeCallback((x0,x1,x2,x3)=>{if(x0.isNull()){if(skipped++<3)send({s:'botNullSendSkipped',n:skipped});return uint64(0);}return sendOrig(x0,x1,x2,x3);},'uint64',['pointer','pointer','pointer','pointer']);\n keep.push(cb);Interceptor.replace(sendTarget,cb);send({s:'botSendGuardInstalled'});}\n\n// Second bot-network crash: lookup 0x3baa1c4 returns a garbage handle (e.g. 0x8e0000) for a bot\n// address and 0x3ba2b8c dereferences it (fault at 0x3ba2b8c from 0x3ba8420). Treat invalid handles as not found.\n{let bad=0;Interceptor.attach(at(0x3baa1c4),{onLeave(r){if(r.isNull())return;\n  if(r.compare(ptr('0x10000000'))<0||(r.and(7).toInt32()!==0)){if(bad++<3)send({s:'botBadChannelHandle',h:r.toString(),n:bad});r.replace(ptr(0));}}});\n send({s:'botChannelGuardInstalled'});}\n\n// Crash reporter: log pc/lr/backtrace for any native fault, then let the normal handling continue.\nProcess.setExceptionHandler(d=>{try{const f=x=>{const m=Process.findModuleByAddress(x);return m?m.name+'+'+x.sub(m.base).toString(16):x.toString();};\n send({s:'botCrash',type:d.type,addr:d.memory?d.memory.address.toString():null,op:d.memory?d.memory.operation:null,pc:f(d.context.pc),lr:f(d.context.lr),\n  bt:Thread.backtrace(d.context,Backtracer.FUZZY).slice(0,10).map(f),tid:Process.getCurrentThreadId()});}catch(e){}return false;});\nlet newClients=[];\nInterceptor.attach(at(0x3cd9fc4),{onLeave(r){if(!inCall)return;try{const n=at(0x54cafa8).readPointer().readS32(),sl=at(0x54cafb0).readPointer();for(let i=0;i<n;i++){if(sl.add(i*8).readPointer().equals(r)){r.add(0xb668).writeU32(1);newClients.push(i);send({s:'botClientFlagged',slot:i});}}}catch(e){send({s:'botFlagError',e:String(e)});}}});\nlet armed=false,uiDone=false,svStage=0,svAt=0,nCalls=0,cur=null;const queue=[],entered={},teamOf={};let friendsLeft=E.friends||0;const zeroCmd=Memory.alloc(0x400);keep.push(zeroCmd);\nglobalThis.wzmBotArm=()=>{if(!armed){armed=true;if(E.skipParty){uiDone=true;svStage=1;svAt=Date.now();}send({s:'botInjectArmed',count:COUNT,team:TEAM});}};\nInterceptor.attach(at(0x337c1c0),{onEnter(){\n if(!armed||uiDone)return;uiDone=true;\n try{\n  const p=getParty();const before=fields(p);\n  if(p.add(0x4650).readU64().equals(0))p.add(0x4650).writeU64(uint64('0x0f0f1ce5'));\n  if(p.add(0x54).readU64().equals(0))p.add(0x54).writeU64(uint64('0x0f0f1ce5'));\n  let r=-1;\n  // Adding bot party members (pa_manage_bots) makes the party send real connect packets that crash the\n  // network-thread handler (fault 0x7405176050 from 0x3ccde74). addtestclient only needs the two fields.\n  if(E.partyMembers){req.writeU32(DIFF);req.add(4).writeS32(-1);req.add(8).writeS32(COUNT);req.add(12).writeU8(0);req.add(13).writeU8(TEAM);r=apply(p,req);}\n  send({s:'botInjectParty',before,applyRet:r,after:fields(p),slots:slots()});\n  svStage=1;svAt=Date.now();\n }catch(e){send({s:'botInjectError',where:'party',error:String(e),stack:e.stack});}\n}});\n// Perf: runs every server tick; detaches itself once bot injection has finished (stage 5) or failed (9).\nlet tickHook=null,tickGone=false;\ntickHook=Interceptor.attach(at(0x3cf10e0),{onEnter(){\n if(svStage>=5){if(!tickGone){tickGone=true;setTimeout(()=>{try{tickHook.detach();send({s:'botTickDetached'});}catch(e){}},0);}return;}\n if(!svStage)return;const dt=Date.now()-svAt;\n try{\n  if(svStage===1&&dt>2000){svStage=2;\n   // runs that worked started bot ids at 8 (ids 3-7 used by party connects); the first bot at id 3 faulted\n   try{const sv=at(0x54d1118).readPointer().readPointer();const c=sv.add(0x80).readU16();if(c<5){sv.add(0x80).writeU16(E.botIdStart||5);send({s:'botCounterBumped',from:c,to:E.botIdStart||5});}}catch(e){send({s:'botCounterErr',e:String(e)});}\nsend({s:'botInjectSlots2s',slots:slots()});svAt=Date.now();}\n  else if(svStage===2&&dt>300){\n   let job=queue.shift();\n   if(!job){if(nCalls>=CALLS){svStage=4;svAt=Date.now();return;}nCalls++;job=[0x3cd64e8,0,0,'addtest'];}\n   cur=job;cg.add(16).writeU32(job[3]==='addtest'?1:0);cg.add(0x18).writePointer(at(job[0]));cg.add(0x20).writePointer(ptr(job[1]));cg.add(0x28).writePointer(ptr(job[2]));\n   cg.writeU64(1);svStage=3;svAt=Date.now();}\n  else if(svStage===3&&cg.readU64().equals(0)&&dt>300){\n   cg.add(16).writeU32(0);const ret=cg.add(8).readPointer();\n   if(cur[3]==='addtest'){\n    send({s:'botAddTestClient',ent:ret.toString(),slots:slots()});\n    if(!ret.isNull()){const n=at(0x54cafa8).readPointer().readS32(),sl=at(0x54cafb0).readPointer();\n     for(let i=1;i<Math.min(n,20);i++){const c=sl.add(i*8).readPointer();if(c.isNull())continue;const k=c.toString();\n      if(c.add(8).readU8()===5&&c.add(0xb668).readU32()===1&&!entered[k]){entered[k]=1;const tb=(E.friends&&friendsLeft-->0)?2:(E.teamByte===undefined?1:E.teamByte);c.add(0x280).writeU8(tb);teamOf[i]=tb;send({s:'botTeamSet',slot:i,teamByte:tb});queue.push([0x3cd53bc,c,0,'gamestate '+i]);queue.push([0x3cd0a00,c,zeroCmd,'enterworld '+i]);}}}\n   }else{\n    if(cur[3].startsWith('enterworld')&&E.teamFields!==false){try{\n     const i=parseInt(cur[3].split(' ')[1]);const ent=at(0x54beee0).readPointer().readPointer().add(0x18).readPointer().add(i*0x6f0);\n     const tb=teamOf[i]||1;const g=ent.add(0x170).readPointer(),c=ent.add(0x178).readPointer();\n     const before=[g.add(0x1a8).readU8(),g.add(0x1ac).readU8(),c.add(0x10).readU8()];\n     // candidate team fields (value 2 = your team for you and every bot): game client +0x1a8/+0x1ac, client info +0x10\n     g.add(0x1a8).writeU8(tb);g.add(0x1ac).writeU8(tb);c.add(0x10).writeU8(tb);\n     send({s:'botTeamFields',slot:i,before,set:tb});}catch(e){send({s:'botTeamFieldsErr',e:String(e)});}}\n    send({s:'botStep',step:cur[3],ret:ret.toString(),slots:slots()});}\n   svStage=2;svAt=Date.now();}\n  else if(svStage===4&&dt>3000){svStage=5;restore();send({s:'botInjectFinal',slots:slots(),members:members(getParty())});}\n }catch(e){svStage=9;try{restore();}catch(_){}send({s:'botInjectError',where:'server',error:String(e),stack:e.stack});}\n}});\nsend({s:'botInjectLoaded',pid:Process.id,oldThunk:oldThunk.toString()});\n}\n";
export const BOTH_SIDES_AI = "// Create genuine marker-2 AI clients on BOTH teams in one pass.\n// Derived from the live-proven add_more_native_ai.js stage machine (creator ->\n// gamestate -> enterworld -> original Veteran setter). The team itself is decided\n// by the host's enter-world team hook (WZM_ENEMY_AI=N): the first N marker-2 bots\n// stay team 1, later ones get team 2 like the local player. This script never\n// writes a team field itself; it only reads the engine team back as evidence.\n// Chains in front of whatever thunk the server veneer already points at (for\n// example the Veteran guard) and links that thunk back when finished.\n{\n'use strict';\nconst b=Process.getModuleByName('libgame.so').base,at=n=>b.add(n);\nconst opt=globalThis.WZM_BOTH_SIDES_AI||{},goal=opt.count===undefined?6:opt.count;\nif(!Number.isInteger(goal)||goal<1||goal>8)throw Error('bot count must be 1..8');\nconst veneer=at(0x3cd7b20);\nif(veneer.readU32()!==0x58000050||veneer.add(4).readU32()!==0xd61f0200)throw Error('server veneer mismatch');\nif(at(0x3cd6960).readU32()!==0xd10243ff)throw Error('creator opcode mismatch');\nif(at(0x265ea3c).readU32()!==0xd10183ff)throw Error('difficulty setter opcode mismatch');\nconst prior=veneer.add(8).readPointer();\nconst keep=globalThis.wzmBothSidesAiKeep=[];\nconst gate=Memory.alloc(0x80),code=Memory.alloc(Process.pageSize),zero=Memory.alloc(0x400);\nkeep.push(gate,code,zero);Memory.protect(code,Process.pageSize,'rwx');\nconst names=[];\nfor(let i=0;i<goal;i++){const nm=Memory.allocUtf8String('');keep.push(nm);names.push(nm);}\n{const w=new Arm64Writer(code,{pc:code});\n w.putPushRegReg('x29','lr');\n for(const [x,y] of [['x0','x1'],['x2','x3'],['x4','x5'],['x6','x7']])w.putPushRegReg(x,y);\n w.putLdrRegAddress('x16',gate);w.putLdrRegRegOffset('x17','x16',0);w.putCbzRegLabel('x17','skip');\n w.putStrRegRegOffset('xzr','x16',0);\n for(let i=0;i<4;i++)w.putLdrRegRegOffset('x'+i,'x16',0x20+i*8);\n w.putLdrRegRegOffset('x16','x16',0x18);w.putBlrReg('x16');\n w.putLdrRegAddress('x16',gate);w.putStrRegRegOffset('x0','x16',8);\n w.putLabel('skip');\n for(const [x,y] of [['x6','x7'],['x4','x5'],['x2','x3'],['x0','x1']])w.putPopRegReg(x,y);\n w.putPopRegReg('x29','lr');\n w.putLdrRegAddress('x16',prior);w.putBrReg('x16');w.flush();}\nMemory.patchCode(veneer.add(8),8,p=>p.writePointer(code));\nfunction restore(){Memory.patchCode(veneer.add(8),8,p=>p.writePointer(prior));}\nfunction slots(){const n=at(0x54cafa8).readPointer().readS32(),a=at(0x54cafb0).readPointer(),o=[];\n for(let i=0;i<Math.min(n,24);i++){const c=a.add(i*8).readPointer();if(c.isNull()||!c.add(8).readU8())continue;\n  const ai=c.add(0x6c0).readPointer();o.push({slot:i,client:c.toString(),state:c.add(8).readU8(),flag:c.add(0xb668).readU32(),ai:ai.isNull()?'0':ai.toString()});}return o;}\nfunction teamOf(slot){try{return at(0x54bfb78).readPointer().readPointer().add(slot*0x31270).add(0x7f20).readU8();}catch(e){return null;}}\nfunction tally(){const rows=slots().filter(r=>r.flag===2);const byTeam={};for(const r of rows){const t=teamOf(r.slot);byTeam[t]=(byTeam[t]||0)+1;}\n return {genuineAi:rows.length,byTeam,slots:rows.map(r=>({slot:r.slot,team:teamOf(r.slot),state:r.state}))};}\nconst active=new Set();\nInterceptor.attach(at(0x3cd6960),{onEnter(){active.add(Process.getCurrentThreadId());},onLeave(){active.delete(Process.getCurrentThreadId());}});\nInterceptor.attach(at(0x3ccc9b0),{onEnter(a){if(!active.has(Process.getCurrentThreadId()))return;const p=a[0];if(p.readU32()===0)p.writeByteArray([0,255,0,255,0,0]);p.add(6).writeU8(1);send({s:'bothSidesConnectionGuard'});}});\nlet armed=false,stage=0,current=null,lastAt=0;\nconst created=[],seen=new Set();\nfunction queue(fn,args){if(gate.readU64().equals(1))throw Error('gate busy');\n gate.add(0x18).writePointer(at(fn));for(let i=0;i<4;i++)gate.add(0x20+i*8).writePointer(args[i]||ptr(0));\n gate.writeU64(1);lastAt=Date.now();}\nglobalThis.wzmBotArm=()=>{\n if(armed)return;const rows=slots();\n if(!rows.some(r=>r.slot===0&&r.state===7))throw Error('local player not in world');\n rows.forEach(r=>seen.add(r.client));armed=true;\n send({s:'bothSidesArmed',pid:Process.id,goal,already:tally(),rows});\n};\nInterceptor.attach(at(0x3cf10e0),{onEnter(){if(!armed||stage===99)return;try{\n if(gate.readU64().equals(1)){if(Date.now()-lastAt>8000)throw Error('gate timeout at stage '+stage);return;}\n if(Date.now()-lastAt<250)return;\n if(stage===0){\n  if(created.length===goal){stage=99;restore();\n   send({s:'botInjectFinal',experiment:'both_sides_native_ai',created,summary:tally(),rows:slots()});return;}\n  stage=1;queue(0x3cd6960,[names[created.length],ptr(0),ptr(0),ptr(0)]);return;}\n if(stage===1){const result=gate.add(8).readPointer(),rows=slots();\n  const row=rows.find(r=>r.flag===2&&!seen.has(r.client));\n  if(result.isNull()||!row)throw Error('creator returned no new marker-2 client');\n  seen.add(row.client);current={slot:row.slot,client:row.client};stage=2;queue(0x3cd53bc,[ptr(row.client)]);return;}\n if(stage===2){const row=slots().find(r=>r.client===current.client);\n  if(!row||row.state!==6)throw Error('gamestate did not reach state 6');\n  stage=3;queue(0x3cd0a00,[ptr(row.client),zero]);return;}\n if(stage===3){const row=slots().find(r=>r.client===current.client);\n  if(!row||row.state!==7||row.flag!==2)throw Error('enterworld state/marker mismatch');\n  const ai=ptr(row.ai);if(ai.isNull())throw Error('AI pointer missing after enter');\n  stage=4;queue(0x265ea3c,[ai,ptr(3)]);return;}\n if(stage===4){const row=slots().find(r=>r.client===current.client),ai=ptr(row.ai),df=ai.add(0xb258).readU8();\n  if(df!==3)throw Error('Veteran readback failed');\n  const team=teamOf(row.slot);\n  created.push({slot:row.slot,team,difficulty:df});\n  send({s:'bothSidesVeteran',slot:row.slot,team,difficulty:df,n:created.length});\n  current=null;stage=0;lastAt=Date.now();}\n}catch(e){stage=99;restore();send({s:'botInjectError',experiment:'both_sides_native_ai',error:String(e),created,rows:slots()});}}});\nsend({s:'bothSidesLoaded',pid:Process.id,goal,guardThunk:prior.toString()});\n}\n";
export const VETERAN_GUARD = "// Apply original Veteran AI setter to every active genuine AI bot, both teams.\n// Existing tested host + party-network guards must remain retained.\n{\n'use strict';\nconst BOT_DIFF=(globalThis.WZM_BOT_DIFF===undefined)?3:globalThis.WZM_BOT_DIFF; // 0 Recruit,1 Regular,2 Hardened,3 Veteran\nconst b=Process.getModuleByName('libgame.so').base,at=n=>b.add(n),keep=globalThis.wzmNativeAiDifficultyKeep=[];\nconst v=at(0x3cd7b20);if(v.readU32()!==0x58000050||v.add(4).readU32()!==0xd61f0200)throw Error('server veneer mismatch');\nif(at(0x265ea3c).readU32()!==0xd10183ff)throw Error('difficulty setter opcode mismatch');\nconst prior=v.add(8).readPointer(),gate=Memory.alloc(80),code=Memory.alloc(Process.pageSize),name=Memory.allocUtf8String(''),zero=Memory.alloc(0x400);\nkeep.push(gate,code,name,zero);Memory.protect(code,Process.pageSize,'rwx');\n{const w=new Arm64Writer(code,{pc:code});w.putPushRegReg('x29','lr');for(const[x,y]of[['x0','x1'],['x2','x3'],['x4','x5'],['x6','x7']])w.putPushRegReg(x,y);\nw.putLdrRegAddress('x16',gate);w.putLdrRegRegOffset('x17','x16',0);w.putCbzRegLabel('x17','skip');w.putStrRegRegOffset('xzr','x16',0);\nfor(let i=0;i<4;i++)w.putLdrRegRegOffset('x'+i,'x16',0x20+i*8);w.putLdrRegRegOffset('x16','x16',0x18);w.putBlrReg('x16');w.putLdrRegAddress('x16',gate);w.putStrRegRegOffset('x0','x16',8);w.putLabel('skip');for(const[x,y]of[['x6','x7'],['x4','x5'],['x2','x3'],['x0','x1']])w.putPopRegReg(x,y);w.putPopRegReg('x29','lr');w.putLdrRegAddress('x16',prior);w.putBrReg('x16');w.flush();}\nMemory.patchCode(v.add(8),8,p=>p.writePointer(code));\nfunction restore(){Memory.patchCode(v.add(8),8,p=>p.writePointer(prior));}\nfunction slots(){const n=at(0x54cafa8).readPointer().readS32(),a=at(0x54cafb0).readPointer(),o=[];for(let i=0;i<Math.min(n,20);i++){const c=a.add(i*8).readPointer();if(c.isNull()||!c.add(8).readU8())continue;const ai=c.add(0x6c0).readPointer();o.push({slot:i,client:c.toString(),state:c.add(8).readU8(),flag:c.add(0xb668).readU32(),ai:ai.toString()});}return o;}\nlet armed=false,stage=0,waitAt=0,client=null,slot=-1,pending=null,lastScan=0,reported=false;const applied=[];const before=new Set(slots().map(x=>x.client));\nfunction queue(fn,args){gate.add(0x18).writePointer(at(fn));for(let i=0;i<4;i++)gate.add(0x20+i*8).writePointer(args[i]||ptr(0));gate.writeU64(1);waitAt=Date.now();}\nglobalThis.wzmBotArm=()=>{armed=true;send({s:'nativeAiDifficultyArmed',pid:Process.id,before:slots()});};\nInterceptor.attach(at(0x3cf10e0),{onEnter(){if(!armed||stage===9)return;try{\n if(gate.readU64().equals(1)||Date.now()-waitAt<250)return;\n if(stage===2){if(Date.now()-lastScan<1000)return;lastScan=Date.now();pending=slots().filter(r=>r.flag===2 && ptr(r.ai).add(0xb258).readU8()!==BOT_DIFF);if(!pending.length)return;stage=0;}\n if(stage===0){if(pending===null)pending=slots().filter(r=>r.flag===2);if(!pending.length){stage=2;lastScan=Date.now();if(!reported){reported=true;send({s:'botInjectFinal',experiment:'all_native_ai_veteran_guard',applied,rows:slots()});}return;}const row=pending.shift();client=ptr(row.client);slot=row.slot;const ai=client.add(0x6c0).readPointer();if(ai.isNull()||!Process.findRangeByAddress(ai))throw Error('AI data absent');send({s:'nativeAiDifficultyBefore',slot,ai:ai.toString(),difficulty:ai.add(0xb258).readU8()});stage=1;queue(0x265ea3c,[ai,ptr(BOT_DIFF)]);return;}\n if(stage===1){const ai=client.add(0x6c0).readPointer(),value=ai.add(0xb258).readU8();if(value!==BOT_DIFF)throw Error('Veteran readback mismatch');const g=at(0x54bfb78).readPointer().readPointer().add(slot*0x31270);const result={slot,team:g.add(0x7f20).readU8(),difficulty:value,label:'Veteran'};applied.push(result);send({s:'veteranEnforced',...result});stage=0;}\n\n\n }catch(e){stage=9;restore();send({s:'botInjectError',experiment:'all_native_ai_veteran',error:String(e),rows:slots()});}}});\nsend({s:'nativeAiDifficultyLoaded',pid:Process.id,code:code.toString(),gate:gate.toString()});\n}\n";
export const PREVIEW_GUARD = "// Memory-only guard for the main-menu weapon picker crash (7 Nov 2026).\n// 0x355ca54(x0, clientIdx, weaponName) updates the frontend preview client's weapon.\n// Offline there is no frontend local client: the client table (GOT 0x54bcd30 count,\n// 0x54bcd38 active flag, 0x54bcd40 array) is empty, x21 stays 0 and the function reads\n// 0x147f64+0x2394+0x10 = 0x14a308 -> SIGSEGV (seen on selecting AK-74).\n// When the client slot is missing, return 0, which is the function's own \"nothing done\" exit.\nconst b = Process.getModuleByName('libgame.so').base;\nconst got = o => b.add(o).readPointer();\nconst f = b.add(0x355ca54);\nlet skipped = 0, passed = 0;\nif (f.readU32() !== 0xd10703ff) {\n  send({ s: 'previewGuardBadOpcode', op: f.readU32().toString(16) });\n} else {\n  const orig = new NativeFunction(f, 'int', ['pointer', 'int', 'pointer']);\n  Interceptor.replace(f, new NativeCallback(function (a, c, name) {\n    let ok = false;\n    try {\n      const cnt = got(0x54bcd30).readS32(), flag = got(0x54bcd38).readS32();\n      ok = flag !== 0 && cnt > 0 && !got(0x54bcd40).readPointer().isNull();\n    } catch (e) { ok = false; }\n    if (!ok) {\n      skipped++;\n      if (skipped <= 5) { let n = ''; try { n = name.readCString(64); } catch (e) {} send({ s: 'previewGuardSkip', n, skipped }); }\n      return 0;\n    }\n    passed++;\n    return orig(a, c, name);\n  }, 'int', ['pointer', 'int', 'pointer']));\n  send({ s: 'previewGuardInstalled' });\n}\n";
export const WEAPON_CATALOG = "\nconst b=Process.getModuleByName('libgame.so').base,at=x=>b.add(x),p=at(0x635b940+60*0xd0);\nconst base=p.readPointer(),stride=p.add(20).readU32(),capacity=p.add(16).readU32(),bits=p.add(0xb0).readPointer();\nif(stride!==0x530||capacity>2048)throw Error('pool layout mismatch');\nconst refs=[];for(let i=0;i<capacity;i++){if(!(bits.add((i>>>5)*4).readU32()&(0x80000000>>>(i&31))))continue;\n const asset=base.add(i*stride);try{const name=asset.add(8).readPointer().readUtf8String();if(name&&/^[a-zA-Z0-9_]{1,120}$/.test(name))refs.push({index:i,name,asset:asset.toString()});}catch(e){send({kind:'bad_asset',index:i,error:String(e)});}}\nsend({kind:'catalog',capacity,stride,refs,countBefore:at(0x6cb1ab0).readU32()});\nif(true){\n if(at(0x28fe554).readU32()!==0xd101c3ff)throw Error('callback opcode mismatch');\n const register=new NativeFunction(at(0x28fe554),'void',['int','pointer']);let pos=0,ended=false;\n const strings=refs.map(r=>Memory.allocUtf8String(r.name));\n Interceptor.attach(at(0x337c1c0),{onEnter(){if(ended)return;\n  try{\n   const st=at(0x54bb7e8).readPointer().add(8).readU32();\n   if(st>=5||at(0x6cb1abc).readU8()!==0)throw Error('frontend guard rejected');\n   for(let j=0;j<4&&pos<refs.length;j++,pos++)register(pos+1,strings[pos]);\n   if(pos%40===0)send({kind:'progress',processed:pos,count:at(0x6cb1ab0).readU32()});\n   if(pos===refs.length){ended=true;send({kind:'done',processed:pos,count:at(0x6cb1ab0).readU32(),busy:at(0x6cb1abc).readU8()});}\n  }catch(e){ended=true;send({kind:'done',error:String(e),processed:pos});}\n }});\n}\n";
