export const LUA_OFFLINE_UNLOCKS = "-- Session-only offline ownership override for cosmetic/weapon items.\n-- Wraps the game's own PROGRESSION unlock query; the original function remains\n-- restorable through _G.WZM_UNLOCK.restore(). Nothing on disk is patched.\nlocal S=rawget(_G,'WZM_UNLOCK')\nif not S then S={enabled=true,queries=0,byType={},originals={},last=''};rawset(_G,'WZM_UNLOCK',S) end\nlocal P=rawget(_G,'PROGRESSION')\nlocal L=rawget(_G,'LOOT')\nif type(P)~='table' or type(L)~='table' or type(L.itemTypes)~='table' then return 'not ready: progression/loot missing' end\nlocal key,orig\nfor k,v in pairs(P) do if tostring(k):find('13d8bd2b211db6cc',1,true) then key,orig=k,v end end\nif type(orig)~='function' then return 'unlock query not found' end\nlocal T=L.itemTypes\nlocal allow={}\nlocal names={'WEAPON','ATTACHMENT','CAMO','OPERATOR','OPERATOR_SKIN','OPERATOR_EXECUTION','OPERATOR_TAUNT',\n 'RETICLE','CHARM','STICKER','GUN_SCREEN','EMBLEM','PLAYERCARD','SPRAYS','WATCH','GESTURES','EMOTE','QUIP',\n 'PARACHUTE','CONTRAIL','VEHICLE_CAMO','VEHICLE_HORN','VEHICLE_TRACK','LOAD_SCREEN','LEVEL_ICON','PLEA','ROLE',\n 'SPECIAL','UPGRADE','PERK','STREAK','LETHAL','TACTICAL','EQUIPMENT'}\nfor _,n in ipairs(names) do local v=T[n]; if v~=nil then allow[v]=n end end\nif not S.originals[key] then\n  S.originals[key]=orig\n  P[key]=function(c,itemType,ref,...)\n    if S.enabled and ref~=nil and ref~='' and ref~='none' and allow[itemType] then\n      local n=allow[itemType]\n      S.queries=S.queries+1\n      S.byType[n]=(S.byType[n] or 0)+1\n      if S.queries<=6 then S.last=S.last..n..'='..tostring(ref)..'; ' end\n      return true\n    end\n    return orig(c,itemType,ref,...)\n  end\nend\nS.restore=function()\n  for k,f in pairs(S.originals) do P[k]=f end\n  S.originals={}; S.enabled=false\nend\nlocal r={} for _,n in pairs(allow) do r[#r+1]=n end table.sort(r)\nreturn 'installed on '..tostring(key)..' types='..table.concat(r,',')\n";
export const LUA_CLIENT_FENCE = "-- Session-only: report the CLIENT_CONNECT native fence as complete (4) for the offline frontend.\n-- Gear Up / loadouts wait on it; offline the frontend local client never reaches it (stays 2/8).\nlocal function fn(t,h) for k,v in pairs(t or {}) do if tostring(k):find(h,1,true) then return k,v end end end\nlocal S=rawget(_G,'WZM_CLIENT_FENCE')\nif not S then S={};rawset(_G,'WZM_CLIENT_FENCE',S) end\nif not S.orig then\n local k,q=fn(Fences,'b06c6d08978b8c65')\n if not q then return 'fence query missing' end\n S.key=k;S.orig=q\n Fences[k]=function(c,name,...) if name=='CLIENT_CONNECT' then return 4 end return S.orig(c,name,...) end\nend\nreturn 'CLIENT_CONNECT now '..tostring(Fences[S.key](0,'CLIENT_CONNECT'))..' (orig '..tostring(S.orig(0,'CLIENT_CONNECT'))..')'\n";
export const LUA_SEED_LOADOUTS = "-- Re-seed every private/ranked loadout class in the running process, then report.\n-- Ids come from the local WEAPON.*LootID constants (no server catalog needed).\n-- Session-only: the DDL nodes are the game's own, written through :set().\nlocal out={}\nlocal function add(k,v) out[#out+1]=k..'='..tostring(v) end\nlocal PD=rawget(_G,'PLAYER_DATA')\nlocal pdo\nfor k,v in pairs(PD or {}) do if tostring(k):find('08b73907b55c4d71',1,true) then pdo=v end end\nif type(pdo)~='function' then return 'no pdo' end\nlocal W=rawget(_G,'WEAPON')\n-- loadout kit: primary, secondary, melee-ish tertiary slots 0/1/2\nlocal kits={\n  {'WZM-1', W.M4LootID, W.DaemonPistolLootID, W.KnifeLootID},\n  {'WZM-2', W.M4LootID, W.MXGuardianLootID, W.PickaxeLootID},\n  {'WZM-3', W.M4LootID, W.DaemonPistolLootID, W.ChainsawLootID},\n  {'WZM-4', W.M4LootID, W.LachmannShrouadLootID, W.KnifeLootID},\n  {'WZM-5', W.M4LootID, W.DaemonPistolLootID, W.SpearBaseLootID},\n}\nlocal function gv(n)\n  local a,b=pcall(function() return n:get() end)\n  if not a then return 'ERR' end\n  return b\nend\nlocal function setn(n,val)\n  local a,b=pcall(function() return n:set(val) end)\n  return tostring(a)..':'..tostring(b):sub(1,30)\nend\nlocal groups={3,4,6}\nlocal report={}\nfor _,g in ipairs(groups) do\n  local ok,root=pcall(pdo,0,g)\n  if ok and root~=nil then\n    local o,lo=pcall(function() return root.loadouts end)\n    if o and lo~=nil then\n      local done=0\n      for i=0,4 do\n        local o2,l=pcall(function() return lo[i] end)\n        if o2 and l~=nil then\n          local kit=kits[i+1]\n          if kit then\n            local r1=setn(l.name,kit[1])\n            local r2=setn(l.weaponSetups[0].weaponLootID,kit[2])\n            local r3=setn(l.weaponSetups[1].weaponLootID,kit[3])\n            local r4=setn(l.weaponSetups[2].weaponLootID,kit[4])\n            -- perks (7 Nov): empty perk slots render as magenta squares. Fill empty ones only.\n            -- loot IDs read back after equipping in the UI: Survivor, Quartermaster, Ghost\n            local perks={30626,30605,30637}\n            for j=0,2 do\n              local cur=gv(l.perkLootIDs[j])\n              if cur==0 or cur=='ERR' then setn(l.perkLootIDs[j],perks[j+1]) end\n            end\n            local chk=gv(l.weaponSetups[0].weaponLootID)\n            report[#report+1]='g'..g..'i'..i..' name='..tostring(gv(l.name))..' p='..tostring(chk)..' s='..tostring(gv(l.weaponSetups[1].weaponLootID))..' t='..tostring(gv(l.weaponSetups[2].weaponLootID))..' w='..r2..' perks='..tostring(gv(l.perkLootIDs[0]))..'/'..tostring(gv(l.perkLootIDs[1]))..'/'..tostring(gv(l.perkLootIDs[2]))\n            done=done+1\n          end\n        end\n      end\n      add('g'..g..'_classes',done)\n    end\n  end\nend\nadd('report',table.concat(report,' | '):sub(1,900))\nreturn table.concat(out,'\\n'):sub(1,1300)\n";
export const LUA_UNLOCKS_EXT = "-- Session-only: the \"is unlocked\" query (xhash 13d8bd2b211db6cc) exists not only in\n-- PROGRESSION (offline_unlocks.lua) but in OPERATOR, OPERATOR_SKIN, LOOT and other\n-- per-item tables. Offline each answered false, so the Operators screen showed\n-- \"No items available\" and skins were padlocked. Make every copy answer true.\n-- Idempotent; restore with _G.WZM_UNLOCK_EXT.restore().\nlocal T=rawget(_G,'WZM_OPT') if T and T.restore then T.restore() rawset(_G,'WZM_OPT',nil) end\nlocal S=rawget(_G,'WZM_UNLOCK_EXT')\nif not S then S={q=0,orig={},done={},byTable={}} rawset(_G,'WZM_UNLOCK_EXT',S) end\nS.done=S.done or {}\nS.byTable=S.byTable or {}\nlocal added={}\nfor g,tb in pairs(_G) do\n  if type(g)=='string' and g~='PROGRESSION' and g:match('^[A-Z][A-Z_]+$') and type(tb)=='table' and not S.done[g] then\n    for k,f in pairs(tb) do\n      if type(f)=='function' and tostring(k):find('13d8bd2b211db6cc',1,true) then\n        S.orig[#S.orig+1]={tb,k,f}; S.done[g]=true; added[#added+1]=g\n        tb[k]=function(...)\n          S.q=S.q+1; S.byTable[g]=(S.byTable[g] or 0)+1\n          return true\n        end\n      end\n    end\n  end\nend\nS.restore=function() for _,x in ipairs(S.orig) do x[1][x[2]]=x[3] end S.orig={} S.done={} end\nlocal all={} for g in pairs(S.done) do all[#all+1]=g end table.sort(all)\nreturn 'added '..table.concat(added,',')..' | all '..table.concat(all,',')\n";
export const LUA_UNLOCKS_LEVEL = "-- Session-only: level-gated items (equipment, perks, streaks, field upgrades) ask\n-- PROGRESSION.33568d3533d63f69(controller, itemID) -> false offline (profile level 1).\n-- Answer true for every real item id. Restore with _G.WZM_UNLOCK_LVL.restore().\nlocal P=rawget(_G,'PROGRESSION')\nlocal S=rawget(_G,'WZM_UNLOCK_LVL')\nif S and S.restore then S.restore() end\nS={orig={},q=0};rawset(_G,'WZM_UNLOCK_LVL',S)\nfor k,f in pairs(P) do\n  if type(f)=='function' and tostring(k):find('33568d3533d63f69',1,true) then\n    S.orig[#S.orig+1]={k,f}\n    P[k]=function(c,id,...) if id~=nil then S.q=S.q+1; return true end return f(c,id,...) end\n  end\nend\nS.restore=function() for _,x in ipairs(S.orig) do P[x[1]]=x[2] end S.orig={} end\nreturn 'level unlock wrapped: '..#S.orig\n";
export const LUA_OPEN_GEAR_UP = "local o={}\nlocal M=rawget(_G,'MobileMainMenuButtons');local gear\nfor k,v in pairs(M or {}) do if tostring(k):find('2b8a71f2b33a70b3',1,true) then gear=v end end\nfor k,v in pairs(gear or {}) do o[#o+1]='gear.'..tostring(k)..'='..tostring(v) end\nlocal FM=LUI.FlowManager;local fns={}\nfor k,v in pairs(FM) do if type(v)=='function' then fns[#fns+1]=tostring(k) end end\ntable.sort(fns);o[#o+1]='FlowManager: '..table.concat(fns,','):sub(1,1500)\nlocal ok,r=xpcall(function() return FM.RequestAddMenu(gear.menuName,true,0,false,{},true) end,function(e) return tostring(e)..'\\n'..debug.traceback('',2) end)\no[#o+1]='RequestAddMenu -> '..tostring(ok)..' '..tostring(r):sub(1,1500)\nreturn table.concat(o,'\\n')\n";
export const LUA_CHECK_UNLOCK = "return 'unlock='..tostring(rawget(_G,'WZM_UNLOCK')~=nil)..' ext='..tostring(rawget(_G,'WZM_UNLOCK_EXT')~=nil)..' level='..tostring(rawget(_G,'WZM_UNLOCK_LVL')~=nil)\n";
export const LUA_SKIP_ONLINE_FENCES = "-- Session-only: treat fences that depend on the shut-down servers as passed.\n-- Re-run periodically: LUI rebuilds wipe it, and the marker shows when that happened.\n-- Play button status model: 0/4 Finalizing Install, 1 Play, 3 Cancel, 5 party-size warning.\n-- Nothing sets it correctly offline, so select Play once the hub exists.\nlocal function play_button()\n local function find(e,id,d)\n  if d>12 then return end\n  if tostring(e.id)==id then return e end\n  local c=e:getFirstChild()\n  while c do local r=find(c,id,d+1); if r then return r end; c=c:getNextSibling() end\n end\n local b=find(LUI.primaryRoot,\"xhash: #x0d6362796dd5f31d1\",0)\n if not b then return false end\n local _,src=next((b:GetDataSource()))\n local status=src._inputDataSources[1]\n -- Something republishes the status every few seconds, so hold it from the navigator frame.\n local W0=rawget(_G,\"_WZM\")\n local frame=MenuNavigator.Frame\n MenuNavigator.Frame=function(...)\n  if status:GetValue(0)~=1 then status:SetValue(0,1); W0.held=(W0.held or 0)+1 end\n  return frame(...)\n end\n return true\nend\ndo local W0=rawget(_G,\"_WZM\")\n if W0 then\n  if W0.play then return \"\" end\n  local ok,done=pcall(play_button)\n  if ok and done then W0.play=true; return \"play button ready\" end\n  if not ok and W0.playerr~=tostring(done) then W0.playerr=tostring(done); return \"play button error: \"..W0.playerr end\n  return \"\"\n end\nend\nlocal W={n=0}; rawset(_G,\"_WZM\",W)\nlocal SKIP={onlineServices=1,gamerProfile=1,patch=1,ffotd=1,onlinePlayerstats=1,mainOnlineData=1,platformServices=1,\n playlists=1,exchange=1,churnReward=1,onlineServiceSubscription=1,mpOnlineData=1,fnf=1,fenceSpinner=1,ftue=1,motd=1,dailyLineup=1,uxpcloudsyncinit=1}\nlocal pass=function() return 0 end\nlocal nop=function() end\nlocal C=LUI.FenceGroup\nlocal function apply(self)\n if self._wzm then return end\n self._wzm=true\n for _,f in ipairs(self._fences or {}) do if SKIP[f._name] then f.State=pass; f.Start=nop; f.UpdateState=nop; f.Stop=nop; f._state=0 end end\n W.n=W.n+1\nend\nlocal frame,passes=C.Frame,C.Passes\nC.Frame=function(self,...) apply(self) return frame(self,...) end\nC.Passes=function(self,...) apply(self) return passes(self,...) end\n-- The FTUE (tutorial) layer never exists once the ftue fence is skipped, so give its\n-- getter a null object that absorbs chained calls. Applied at first widget build\n-- because the FTUE module can load after this chunk runs.\nlocal NULL; NULL=setmetatable({},{__index=function() return function() return NULL end end})\nW.null=NULL\n-- Stand-in for player data that normally comes from the servers: any field is another\n-- node, get() is empty, set() and other calls do nothing.\nlocal NODE; NODE=setmetatable({},{__index=function(_,k)\n if k==\"get\" then return function() return 0 end end\n if k==\"set\" then return function() end end\n if k==\"GetValue\" then return function() return 0 end end\n if k==\"GetModel\" then return function(_,c) return DataSources.alwaysLoaded.cdni.pauseStatusCode:GetModel(c or 0) end end\n return NODE end,__call=function() return NODE end})\nW.node=NODE\n-- Lobby getters that return nil with no party. Add a hash here when a menu needs another one.\nlocal LOBBY_NIL={[\"xhash: #x04dae59e12a383b92\"]=1}\n-- Helpers the shipped scripts call but no longer define.\nlocal MISSING={[\"xhash: #x05b161c0d5f530c0d\"]=1}\nlocal function missing_helpers()\n local G=rawget(_G,\"GRID_AND_LIST\")\n if W.grid or type(G)~=\"table\" then return end\n W.grid=true\n local mt=getmetatable(G) or {}\n local old=mt.__index\n mt.__index=function(t,k)\n  if MISSING[tostring(k)] then return function() end end\n  if type(old)==\"function\" then return old(t,k) elseif old then return old[k] end\n end\n setmetatable(G,mt)\nend\nlocal function fix()\n missing_helpers()\n local L=rawget(_G,\"Lobby\")\n if type(L)==\"table\" then\n  W.lobby=W.lobby or {}\n  local keys={} for k,v in pairs(L) do if LOBBY_NIL[tostring(k)] and not W.lobby[tostring(k)] and type(v)==\"function\" then keys[#keys+1]=k end end\n  for _,k in ipairs(keys) do\n   local get=L[k]; W.lobby[tostring(k)]=true\n   rawset(L,k,function(...) local r=get(...); if r==nil then return NODE end return r end)\n  end\n end\n local P=rawget(_G,\"PLAYER_DATA\")\n if not W.pd and type(P)==\"table\" then\n  local keys={} for k,v in pairs(P) do if type(v)==\"function\" then keys[#keys+1]=k end end\n  for _,k in ipairs(keys) do\n   local get=P[k]\n   W.pdo=W.pdo or {}; W.pdo[k]=get\n   rawset(P,k,function(...) local r=get(...); if r==nil then W.pdnil=true; return NODE end return r end)\n  end\n  W.pd=#keys\n end\n local F=rawget(_G,\"FTUE\")\n if not W.layer and type(F)==\"table\" and type(F.GetFTUELayer)==\"function\" then\n  F.GetFTUELayer=function() return NULL end\n  W.layer=true\n end\n -- CONDITIONS[46a3bc59faa7e280] gates FTUE setup; false takes the game's own early return.\n local C2=rawget(_G,\"CONDITIONS\")\n if not W.cond and type(C2)==\"table\" then\n  for k in pairs(C2) do if tostring(k)==\"xhash: #x046a3bc59faa7e280\" then W.condk=k end end\n  if W.condk~=nil then rawset(C2,W.condk,function() return false end); W.cond=true end\n end\nend\nfix()\nlocal B=MenuBuilder\nlocal build=B.BuildRegisteredType\nB.BuildRegisteredType=function(...) fix() return build(...) end\nreturn \"installed layer=\"..tostring(W.layer)..\" cond=\"..tostring(W.cond)..\" pd=\"..tostring(W.pd)\n";
export const LUA_DUMP_LOADOUTS = "-- Read the player's edited loadouts (5 slots) as \"path<TAB>type<TAB>value\" lines for saving to disk.\n-- Source: WZM_SYNC_SRC or the first set that differs from the seeded starters. Read-only.\nlocal PD=rawget(_G,'PLAYER_DATA');local core\nfor k,v in pairs(PD or {}) do if tostring(k):find('08b73907b55c4d71',1,true) then core=v end end\nlocal L=rawget(_G,'LOOT');local refOf\nfor k,f in pairs(L) do if tostring(k):find('c82265f889a5eb28',1,true) then refOf=f end end\nlocal groups={'WZRankedLoadouts','RankedLoadouts','PrivateLoadouts','WZPrivateLoadouts'}\nlocal function primary(r,i) local ok,v=pcall(function() return refOf(r.loadouts[i].weaponSetups[0].weaponLootID:get()) end); return ok and tostring(v) or '' end\nlocal src=rawget(_G,'WZM_SYNC_SRC');local root\nfor _,gn in ipairs(groups) do\n  local ok,r=pcall(core,0,CoD.StatsGroup[gn])\n  if ok and r and (src==gn or (not src and (function() for i=0,4 do local p=primary(r,i); if p~='' and p~='nil' and p~='iw9_ar_mike4' then return true end end end)())) then src=gn root=r break end\nend\nif not root then return 'NOTHING_EDITED' end\nlocal out={'#source\\t'..src}\nlocal function fieldsOf(n)\n  local ks,seen={},{}\n  pcall(function() for k,_ in pairs(n) do if seen[k] then break end; seen[k]=true; if k~='__pad' then ks[#ks+1]=k end; if #ks>64 then break end end end)\n  return ks\nend\nlocal function walk(s,path,depth)\n  if depth>8 then return end\n  local okget,v=pcall(function() return s:get() end)\n  if okget then out[#out+1]=path..'\\t'..type(v)..'\\t'..tostring(v) return end\n  local ks=fieldsOf(s)\n  if #ks>0 then for _,k in ipairs(ks) do local a,c=pcall(function() return s[k] end); if a and c~=nil then walk(c,path..'.'..k,depth+1) end end\n  else local okn,n=pcall(function() return #s end)\n    if okn and type(n)=='number' and n>0 and n<=64 then for i=0,n-1 do local a,c=pcall(function() return s[i] end); if a and c~=nil then walk(c,path..'.'..i,depth+1) end end end\n  end\nend\nfor i=0,4 do walk(root.loadouts[i],tostring(i),0); collectgarbage('collect') end\nreturn table.concat(out,'\\n')\n";
export const WATCH_JS = "'use strict';\n// Keeps skip_online_fences.lua installed and reports Lua errors from the engine's\n// message handler, which runs before the Lua stack unwinds.\nconst b=Process.getModuleByName('libgame.so').base,at=x=>b.add(x);\nconst lVar=at(0x54bcd08).readPointer();\nconst load=new NativeFunction(at(0x4490778),'int',['pointer','pointer','size_t','pointer','pointer']);\nconst pcall=new NativeFunction(at(0x4486bc4),'int',['pointer','int','int','int']);\nconst tostr=new NativeFunction(at(0x4483720),'pointer',['pointer','int','pointer']);\nconst name=Memory.allocUtf8String('=wzm_bridge');\nlet buf=null,len=0,tick=0,inside=false,installs=0;\nconst str=(L,i)=>{const p=tostr(L,i,ptr(0));return p.isNull()?null:p.readUtf8String();};\nfunction run(){\n const L=lVar.readPointer();if(L.isNull())return;\n const top=L.add(0x28).readPointer();inside=true;\n try{let r=load(L,buf,len,name,ptr(0));if(r===0)r=pcall(L,0,1,0);\n  const t=str(L,-1);if(r!==0||t)send({k:'chunk',r,msg:t,installs:++installs});\n }catch(e){send({k:'exc',e:String(e)});}\n L.add(0x28).writePointer(top);inside=false;\n}\nlet hooked=false;\nInterceptor.attach(at(0x337c1c0),{onEnter(){if(!hooked)hooked=hookHandler();if(buf&&(tick++%10===0))run();}});\nconst seen={};let errs=0;\nfunction hookHandler(){\n const handler=at(0xae8c6f0).readPointer();if(handler.isNull())return false;\n send({k:'ready',handler:handler.sub(b).toString()});\n Interceptor.attach(handler,{onEnter(a){this.L=a[0];this.m=null;\n  try{this.m=str(a[0],1);}catch(e){this.m='exc '+e;}\n  const key=String(this.m).slice(0,200);\n  if(!seen[key]&&!inside){inside=true;const L=a[0],top=L.add(0x28).readPointer();\n   try{const c='return debug.traceback(\"\",2)';const cb=Memory.allocUtf8String(c);\n    let r=load(L,cb,c.length,name,ptr(0));if(r===0)r=pcall(L,0,1,0);this.tb=str(L,-1);}catch(e){this.tb='exc '+e;}\n   L.add(0x28).writePointer(top);inside=false;}},\n onLeave(){let t=null;try{t=str(this.L,-1);}catch(e){}\n  const key=String(this.m).slice(0,200);errs++;\n  if(!seen[key]){seen[key]=1;send({k:'lua_error',n:errs,msg:this.m,trace:this.tb||t});}}});\n return true;\n}\n// Asset file opens: one report per path and result, so missing files stand out.\nconst opened={};\nfunction report(path,fd){\n if(path===null||!/zone\\/|\\.xsub|\\.xpak|\\.ff|shard_cache\\/xxh64|\\.dcache/.test(path))return;\n const short=path.replace(/.*\\/files\\//,''),st=fd<0?'FAIL':'ok',key=st+short;\n if(opened[key])return;opened[key]=1;send({k:'file_open',st,path:short});\n}\nfor(const [n,idx] of [['open',0],['__open_2',0],['openat',1],['__openat_2',1],['open64',0]]){\n const a=Module.findGlobalExportByName(n);if(!a)continue;\n Interceptor.attach(a,{onEnter(x){try{this.p=x[idx].readUtf8String();}catch(e){this.p=null;}},onLeave(r){report(this.p,r.toInt32());}});\n}\nfor(const n of ['access','faccessat']){const a=Module.findGlobalExportByName(n);if(!a)continue;\n const idx=n==='access'?0:1;\n Interceptor.attach(a,{onEnter(x){try{this.p=x[idx].readUtf8String();}catch(e){this.p=null;}},onLeave(r){report(this.p,r.toInt32());}});}\nconst zones={};\nInterceptor.attach(at(0x12d5890),{onEnter(a){for(let i=0;i<3;i++){try{const t=a[i].readCString(80);if(t&&/^[ -~]{3,}$/.test(t)&&/\\.(ff|xsub|xpak)|zone/.test(t)){this.z=t;break;}}catch(e){}}},\n onLeave(r){if(this.z&&!zones[this.z]){zones[this.z]=1;send({k:'zone_lookup',z:this.z,r:r.toString()});}}});\nrpc.exports={start(s){buf=Memory.allocUtf8String(s);len=s.length;return true;}};\n";
